// ── 1. Parse fenced JSON from each feed file ──────────────────────────
function parseFencedJSON(fileContent) {
  const match = fileContent.match(/```json\s*([\s\S]*?)\s*```/);
  if (!match) throw new Error('No fenced JSON block found');
  return JSON.parse(match[1]);
}

const gmailRaw    = $('Read Feed – Gmail').first().json.data || '';
const clickupRaw  = $('Read Feed – ClickUp').first().json.data || '';
const projectsRaw = $('Read Feed – Projects').first().json.data || '';

const gmailMessages    = parseFencedJSON(gmailRaw);
const clickupMessages  = parseFencedJSON(clickupRaw);
const projects         = parseFencedJSON(projectsRaw);

// ── 2. Filter out noise ─ LLM doesn't need to classify it ────────────────
const NOISE_SENDERS = [
  'REDACTED-EMAIL',  // ClickUp — keep, useful signal
];

const gmailFiltered = gmailMessages.filter(m => m.gmail_category !== 'noise');

// Drop pure emoji-only ClickUp messages — no signal value
const clickupFiltered = clickupMessages.filter(m => {
  const stripped = (m.text || '').replace(/:[a-z_]+:/g, '').replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{1F1E6}-\u{1F1FF}]/gu, '').trim();
  return stripped.length > 0;
});

// Normalise ClickUp messages onto the common shape (source/message_id/channel/sender/body)
const clickupNormalised = clickupFiltered.map(m => ({
  source: 'clickup_chat',
  source_type: m.source_type,
  message_id: m.comment_id,
  timestamp: m.timestamp,
  channel: m.channel_id || null,
  subject: null,
  sender: m.author,
  body: m.text
}));

// Merge and sort chronologically
const allMessages = [...gmailFiltered, ...clickupNormalised].sort((a, b) => {
  if (!a.timestamp) return 1;
  if (!b.timestamp) return -1;
  return a.timestamp.localeCompare(b.timestamp);
});

// ── 3. Build compact project reference (keywords only ─ keep prompt lean) ─
const projectRef = projects.map(p => ({
  id:           p.id,
  job_name:     p.job_name,
  status:       p.status,
  keywords:     p.keywords,
  clickup_channel_ids: p.clickup_channel_ids || []
}));

// ── 4. Build message list for prompt (strip heavy body content) ───────
const messageList = allMessages.map(m => ({
  id:        m.message_id,
  source:    m.source,
  timestamp: m.timestamp,
  channel:   m.channel || null,
  subject:   m.subject || null,
  sender:    m.sender,
  body:      (m.body || '').substring(0, 400)  // cap body for prompt efficiency
}));

// ── 5. Assemble system prompt ───────────────────────────────
const systemPrompt = `You are a classifier for a personal daily briefing system. Your job is to assign every message to exactly one project ID from the project list, or to a special category.

PROJECTS:
${JSON.stringify(projectRef, null, 2)}

CLASSIFICATION RULES:
- Match messages to projects using keywords, sender names, and subject content.
- ClickUp chat messages: match by the message's "channel" field against a project's clickup_channel_ids list. If channel matches a project's clickup_channel_ids, use that project's id.
- ClickUp notifications (via Gmail): match by task name against project keywords.
- If a message clearly relates to a project: use that project's id (e.g. "ijm-ghana").
- If a message relates to Tim's personal life (non-work): use "PERSONAL".
- If a message is a newsletter, promotion, or automated noise with no decision value: use "NOISE".
- If a message relates to work admin not tied to a specific project (tax, scheduling, general): use "ADMIN".
- If genuinely ambiguous: use "MISC".
- STARRED ITEMS: Any message with source_type "gmail_starred" has been explicitly flagged by Tim as requiring action. Never classify these as NOISE. They must always be assigned to a project, PERSONAL_ADMIN, or MISC.

OUTPUT FORMAT:
Respond with a single JSON array — nothing else, no explanation, no markdown fences. Each element must have exactly these fields:
- "id": the message_id from the input
- "project_id": the project id string or special category
- "confidence": "high", "medium", or "low"
- "note": null, or a brief string only if confidence is low or the match is non-obvious

Example output:
[{"id":"19d6b387e4d457b3","project_id":"ijm-ghana","confidence":"high","note":null}]`;

const userPrompt = `Classify these ${messageList.length} messages:\n${JSON.stringify(messageList, null, 2)}`;

// ── 6. Return data + Benchmarking markers ───────────────────────
return [{
  json: {
    systemPrompt,
    userPrompt,
    allMessages,
    messageCount: messageList.length
  }
}];

// ── 1. Extract raw text from LM Studio response ───────────────────────────
const responseText = $json.choices?.[0]?.message?.content || '';

// ── 1.5 Extract Metadata & Calculate Performance ──────────────────────────
const configNode = $('Config').first()?.json || {};

// Strip extra double quotes if they exist in the pinned string
const rawStartTime = configNode.starttime || "";
const startTimeStr = rawStartTime.replace(/^"|"$/g, ''); 

const modelUsed = configNode.manualModelName || $json.model || 'unknown';

// Resilience: Parse the date safely
const startTime = startTimeStr ? new Date(startTimeStr).getTime() : null;
const endTime = new Date().getTime();

let generationTimeSec = 0;
let tokensPerSecond = 0;

// Validate that startTime is a valid number before doing math
if (startTime && !isNaN(startTime)) {
  generationTimeSec = parseFloat(((endTime - startTime) / 1000).toFixed(2));
}

// Extract token usage
const completionTokens = $json.usage?.completion_tokens || 0;
const totalTokens = $json.usage?.total_tokens || 0;

// Calculate TPS
if (generationTimeSec > 0) {
  tokensPerSecond = parseFloat((completionTokens / generationTimeSec).toFixed(2));
}


// ── 1.6 Format Duration into Min/Sec ──────────────────────────────────────
const mins = Math.floor(generationTimeSec / 60);
const secs = (generationTimeSec % 60).toFixed(1); // Keep 1 decimal point
const durationFormatted = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;

const metadata = {
  model: modelUsed,
  duration: durationFormatted, // e.g., "5m 53.3s"
  generationTimeSeconds: generationTimeSec,
  tokensPerSecond: tokensPerSecond || 0,
  completionTokens,
  totalTokens
};

// ── 2. Strip <think>...</think> block (Qwen3 thinking model) ─────────────
const stripped = responseText.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

// ── 3. Extract JSON — handle any accidental fences the model adds ─────────
let jsonStr = stripped;
const fenceMatch = stripped.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (fenceMatch) jsonStr = fenceMatch[1];

// ── 4. Parse and validate ─────────────────────────────────────────────────
let classifications;
try {
  classifications = JSON.parse(jsonStr);
} catch (e) {
  throw new Error(`JSON parse failed. Raw response was:\n${stripped.substring(0, 500)}`);
}

if (!Array.isArray(classifications)) {
  throw new Error('Expected a JSON array from LLM');
}

// ── 5. Build output — merge classifications back onto original messages ────
const allMessages = $('Code - Build Prompt').first().json.allMessages;
const classMap = {};
for (const c of classifications) {
  classMap[c.id] = c;
}

const categorisedMessages = allMessages.map(m => ({
  ...m,
  project_id:  classMap[m.message_id]?.project_id  || 'MISC',
  confidence:  classMap[m.message_id]?.confidence  || 'low',
  note:        classMap[m.message_id]?.note        || null,
}));


// ── 6. Build summary stats ────────────────────────────────────────────────
const stats = {};
for (const m of categorisedMessages) {
  stats[m.project_id] = (stats[m.project_id] || 0) + 1;
}

// ── 6.5 Build Obsidian Properties (YAML Frontmatter) ──────────────────────
const properties = `---
model: "${metadata.model}"
duration: "${metadata.duration}"
tokens_per_sec: ${metadata.tokensPerSecond}
tokens_completion: ${metadata.completionTokens}
tokens_total: ${metadata.totalTokens}
---`;

const fence = '```';
const content = `${properties}\n\n${fence}json\n${JSON.stringify(categorisedMessages, null, 2)}\n${fence}`;

return [{ json: { content, stats, totalMessages: categorisedMessages.length, metadata } }];

// ── 7. Return payload ─────────────────────────────────────────────────────
return [{ 
  json: { 
    content, 
    stats, 
    totalMessages: categorisedMessages.length,
    metadata 
  } 
}];
